async function readImage(file){
 if(!file||file.size>1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('invalidUpload');
 const bytes=new Uint8Array(await file.slice(0,16).arrayBuffer());const png=bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71,jpg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255,webp=String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!png&&!jpg&&!webp)throw new Error('invalidUpload');
 // Reject animation containers; the preview accepts static raster images only.
 const full=new Uint8Array(await file.arrayBuffer());const view=new DataView(full.buffer);if(png){for(let off=8;off+12<=full.length;){const len=view.getUint32(off);const kind=String.fromCharCode(...full.slice(off+4,off+8));if(kind==='acTL')throw new Error('invalidUpload');if(off+len+12>full.length)break;off+=len+12;}}if(webp){for(let off=12;off+8<=full.length;){const kind=String.fromCharCode(...full.slice(off,off+4));const len=view.getUint32(off+4,true);if(kind==='ANIM'||kind==='ANMF')throw new Error('invalidUpload');if(off+len+8>full.length)break;off+=len+8+(len%2);}}
 let bitmap;try{bitmap=await createImageBitmap(file);}catch{throw new Error('uploadDecodeError');}const width=bitmap.width,height=bitmap.height;bitmap.close();if(width>6000||height>6000||width*height>16000000)throw new Error('invalidUpload');
 const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('uploadDecodeError'));reader.readAsDataURL(file);});return {data,width,height};
}
